using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.SignalR;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

// 1. 强类型客户端方法接口
public interface IChatClient
{
    Task ReceiveMessage(string user, string message, DateTime timestamp);
    Task UserConnected(string userId, string username);
    Task UserDisconnected(string userId);
    Task ReceiveNotification(string message);
}

// 2. Hub 实现：鉴权、分组、生命周期
[Authorize]
public class ChatHub : Hub<IChatClient>
{
    private static readonly ConcurrentDictionary<string, string> Users = new();
    private readonly ILogger<ChatHub> _logger;

    public ChatHub(ILogger<ChatHub> logger)
    {
        _logger = logger;
    }

    public async Task SendMessage(string message)
    {
        var userId = Context.UserIdentifier;
        var username = Users.GetValueOrDefault(userId, "Unknown");
        _logger.LogInformation("{User} sent: {Message}", username, message);
        await Clients.All.ReceiveMessage(username, message, DateTime.UtcNow);
    }

    public async Task SendToGroup(string groupName, string message)
    {
        var username = Users.GetValueOrDefault(Context.UserIdentifier, "Unknown");
        await Clients.Group(groupName).ReceiveMessage(username, message, DateTime.UtcNow);
    }

    public async Task JoinGroup(string groupName)
    {
        await Groups.AddToGroupAsync(Context.ConnectionId, groupName);
        var username = Users.GetValueOrDefault(Context.UserIdentifier, "Unknown");
        await Clients.Group(groupName).ReceiveNotification(username + " joined " + groupName);
    }

    public async Task LeaveGroup(string groupName)
    {
        await Groups.RemoveFromGroupAsync(Context.ConnectionId, groupName);
        var username = Users.GetValueOrDefault(Context.UserIdentifier, "Unknown");
        await Clients.Group(groupName).ReceiveNotification(username + " left " + groupName);
    }

    public override async Task OnConnectedAsync()
    {
        var userId = Context.UserIdentifier;
        var username = Context.User?.Identity?.Name ?? userId;
        Users[userId] = username;
        _logger.LogInformation("{User} connected, ConnectionId: {Id}", username, Context.ConnectionId);
        await Clients.All.UserConnected(userId, username);
        await Clients.Caller.ReceiveNotification("Welcome!");
        await base.OnConnectedAsync();
    }

    public override async Task OnDisconnectedAsync(Exception exception)
    {
        var userId = Context.UserIdentifier;
        Users.TryRemove(userId, out var username);
        _logger.LogInformation("{User} disconnected", username);
        await Clients.All.UserDisconnected(userId);
        await base.OnDisconnectedAsync(exception);
    }
}

// 3. 服务端配置
public static class SignalRSetup
{
    public static IServiceCollection AddAppSignalR(this IServiceCollection services)
    {
        services.AddSignalR(options =>
        {
            options.EnableDetailedErrors = false; // 生产关闭详细错误
            options.KeepAliveInterval = TimeSpan.FromSeconds(15);
            options.ClientTimeoutInterval = TimeSpan.FromSeconds(30);
            options.MaximumReceiveMessageSize = 64 * 1024; // 64KB
        })
        .AddJsonProtocol(o =>
        {
            o.PayloadSerializerOptions.PropertyNamingPolicy =
                System.Text.Json.JsonNamingPolicy.CamelCase;
        });
        // 多实例时加 Redis Backplane:
        // .AddStackExchangeRedis("localhost:6379", options =>
        // {
        //     options.Configuration.ChannelPrefix =
        //         RedisChannel.Literal("signalr_demo");
        // });
        return services;
    }
}
